-- Current scope attributes, account album checkpoints and account invariants.
CREATE TABLE account_album_state (account_id INTEGER PRIMARY KEY NOT NULL REFERENCES identities(id),revision INTEGER NOT NULL DEFAULT 0 CHECK(typeof(revision)='integer' AND revision>=0),snapshot_observed_at REAL CHECK(snapshot_observed_at IS NULL OR (typeof(snapshot_observed_at) IN ('integer','real') AND snapshot_observed_at BETWEEN -1.7976931348623157e308 AND 1.7976931348623157e308)),legacy_cohort_present INTEGER NOT NULL DEFAULT 0 CHECK(typeof(legacy_cohort_present)='integer' AND legacy_cohort_present IN (0,1)),legacy_cohort_observed_at REAL CHECK(legacy_cohort_observed_at IS NULL OR (typeof(legacy_cohort_observed_at) IN ('integer','real') AND legacy_cohort_observed_at BETWEEN -1.7976931348623157e308 AND 1.7976931348623157e308)),CHECK(legacy_cohort_present=1 OR legacy_cohort_observed_at IS NULL)) WITHOUT ROWID;
CREATE TABLE account_albums (account_id INTEGER NOT NULL REFERENCES identities(id),album_id INTEGER NOT NULL REFERENCES albums(id),source TEXT NOT NULL,saved_at REAL CHECK(saved_at IS NULL OR (typeof(saved_at) IN ('integer','real') AND saved_at BETWEEN -1.7976931348623157e308 AND 1.7976931348623157e308)),PRIMARY KEY(account_id,album_id)) WITHOUT ROWID;
CREATE INDEX ix_account_album_release ON account_albums(album_id,account_id);
CREATE TABLE unattributed_album_memberships (album_id INTEGER PRIMARY KEY NOT NULL REFERENCES albums(id),source TEXT NOT NULL,saved_at REAL CHECK(saved_at IS NULL OR (typeof(saved_at) IN ('integer','real') AND saved_at BETWEEN -1.7976931348623157e308 AND 1.7976931348623157e308))) WITHOUT ROWID;
CREATE VIEW saved_album_memberships AS SELECT account_id,album_id,source,saved_at FROM account_albums UNION ALL SELECT NULL,album_id,source,saved_at FROM unattributed_album_memberships;
CREATE INDEX ix_playlist_scope_group ON playlist_scopes(group_name) WHERE group_name IS NOT NULL;
CREATE INDEX ix_playlist_scope_hidden ON playlist_scopes(ref) WHERE hidden=1;
CREATE INDEX ix_playlist_scope_overlap_ignored ON playlist_scopes(ref) WHERE overlap_ignored=1;
CREATE VIEW quarantined_playlists AS SELECT ref ytm,'Generated' name FROM playlist_scopes WHERE origin='tuneconsole' AND adopted=0;
CREATE VIEW saved_albums AS SELECT p.provider_id browse_id,a.title,a.artist,a.year,a.type,a.thumbnail FROM albums a JOIN album_primary_provider_ids p ON p.album_id=a.id AND p.provider='youtube' WHERE EXISTS(SELECT 1 FROM saved_album_memberships m WHERE m.album_id=a.id);
CREATE TRIGGER rec_capture_account_albums_insert AFTER INSERT ON account_albums BEGIN INSERT INTO rec_change_queue(kind,item) VALUES ('refresh','') ON CONFLICT(kind,item) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER rec_capture_account_albums_update AFTER UPDATE ON account_albums WHEN OLD.album_id IS NOT NEW.album_id BEGIN INSERT INTO rec_change_queue(kind,item) VALUES ('refresh','') ON CONFLICT(kind,item) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER rec_capture_account_albums_delete AFTER DELETE ON account_albums BEGIN INSERT INTO rec_change_queue(kind,item) VALUES ('refresh','') ON CONFLICT(kind,item) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER rec_evidence_account_albums_insert AFTER INSERT ON account_albums BEGIN UPDATE rec_preparation SET evidence_changes=evidence_changes+1 WHERE id=1; END;
CREATE TRIGGER rec_evidence_account_albums_update AFTER UPDATE ON account_albums WHEN OLD.album_id IS NOT NEW.album_id BEGIN UPDATE rec_preparation SET evidence_changes=evidence_changes+1 WHERE id=1; END;
CREATE TRIGGER rec_evidence_account_albums_delete AFTER DELETE ON account_albums BEGIN UPDATE rec_preparation SET evidence_changes=evidence_changes+1 WHERE id=1; END;
CREATE TRIGGER rec_capture_unattributed_album_memberships_insert AFTER INSERT ON unattributed_album_memberships BEGIN INSERT INTO rec_change_queue(kind,item) VALUES ('refresh','') ON CONFLICT(kind,item) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER rec_capture_unattributed_album_memberships_update AFTER UPDATE ON unattributed_album_memberships WHEN OLD.album_id IS NOT NEW.album_id BEGIN INSERT INTO rec_change_queue(kind,item) VALUES ('refresh','') ON CONFLICT(kind,item) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER rec_capture_unattributed_album_memberships_delete AFTER DELETE ON unattributed_album_memberships BEGIN INSERT INTO rec_change_queue(kind,item) VALUES ('refresh','') ON CONFLICT(kind,item) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER rec_evidence_unattributed_album_memberships_insert AFTER INSERT ON unattributed_album_memberships BEGIN UPDATE rec_preparation SET evidence_changes=evidence_changes+1 WHERE id=1; END;
CREATE TRIGGER rec_evidence_unattributed_album_memberships_update AFTER UPDATE ON unattributed_album_memberships WHEN OLD.album_id IS NOT NEW.album_id BEGIN UPDATE rec_preparation SET evidence_changes=evidence_changes+1 WHERE id=1; END;
CREATE TRIGGER rec_evidence_unattributed_album_memberships_delete AFTER DELETE ON unattributed_album_memberships BEGIN UPDATE rec_preparation SET evidence_changes=evidence_changes+1 WHERE id=1; END;
CREATE TRIGGER rec_capture_playlist_scope_preferences_insert AFTER INSERT ON playlist_scopes WHEN NEW.group_name IS NOT NULL OR NEW.origin IS NOT NULL BEGIN INSERT INTO rec_change_queue(kind,item) VALUES ('refresh','') ON CONFLICT(kind,item) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER rec_capture_playlist_scope_preferences_update AFTER UPDATE ON playlist_scopes WHEN OLD.group_name IS NOT NEW.group_name OR OLD.origin IS NOT NEW.origin OR OLD.adopted IS NOT NEW.adopted BEGIN INSERT INTO rec_change_queue(kind,item) VALUES ('refresh','') ON CONFLICT(kind,item) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER rec_capture_playlist_scope_preferences_delete AFTER DELETE ON playlist_scopes WHEN OLD.group_name IS NOT NULL OR OLD.origin IS NOT NULL BEGIN INSERT INTO rec_change_queue(kind,item) VALUES ('refresh','') ON CONFLICT(kind,item) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER rec_evidence_playlist_scope_preferences_insert AFTER INSERT ON playlist_scopes WHEN NEW.group_name IS NOT NULL OR NEW.origin IS NOT NULL BEGIN UPDATE rec_preparation SET evidence_changes=evidence_changes+1 WHERE id=1; END;
CREATE TRIGGER rec_evidence_playlist_scope_preferences_update AFTER UPDATE ON playlist_scopes WHEN OLD.group_name IS NOT NEW.group_name OR OLD.origin IS NOT NEW.origin OR OLD.adopted IS NOT NEW.adopted BEGIN UPDATE rec_preparation SET evidence_changes=evidence_changes+1 WHERE id=1; END;
CREATE TRIGGER rec_evidence_playlist_scope_preferences_delete AFTER DELETE ON playlist_scopes WHEN OLD.group_name IS NOT NULL OR OLD.origin IS NOT NULL BEGIN UPDATE rec_preparation SET evidence_changes=evidence_changes+1 WHERE id=1; END;
CREATE UNIQUE INDEX ix_account_active_master ON identities(is_master) WHERE active=1 AND is_master=1;
CREATE TRIGGER owned_playlist_membership_refs_insert BEFORE INSERT ON playlist_membership_refs WHEN NEW.scope_ref IS NOT NULL AND NOT EXISTS(SELECT 1 FROM playlist_scopes s WHERE s.ref=NEW.scope_ref AND (s.kind<>'account' OR s.identity_id=NEW.identity_id)) BEGIN SELECT RAISE(ABORT,'Playlist scope belongs to another account'); END;
CREATE TRIGGER owned_playlist_membership_refs_update BEFORE UPDATE ON playlist_membership_refs WHEN NEW.scope_ref IS NOT NULL AND NOT EXISTS(SELECT 1 FROM playlist_scopes s WHERE s.ref=NEW.scope_ref AND (s.kind<>'account' OR s.identity_id=NEW.identity_id)) BEGIN SELECT RAISE(ABORT,'Playlist scope belongs to another account'); END;
CREATE TRIGGER owned_playlist_library_revisions_insert BEFORE INSERT ON playlist_library_revisions WHEN NEW.scope_ref IS NOT NULL AND NOT EXISTS(SELECT 1 FROM playlist_scopes s WHERE s.ref=NEW.scope_ref AND (s.kind<>'account' OR s.identity_id=NEW.identity_id)) BEGIN SELECT RAISE(ABORT,'Playlist scope belongs to another account'); END;
CREATE TRIGGER owned_playlist_library_revisions_update BEFORE UPDATE ON playlist_library_revisions WHEN NEW.scope_ref IS NOT NULL AND NOT EXISTS(SELECT 1 FROM playlist_scopes s WHERE s.ref=NEW.scope_ref AND (s.kind<>'account' OR s.identity_id=NEW.identity_id)) BEGIN SELECT RAISE(ABORT,'Playlist scope belongs to another account'); END;
CREATE TRIGGER immutable_playlist_scope_identity BEFORE UPDATE OF ref,provider_id,identity_id,kind ON playlist_scopes WHEN NEW.ref IS NOT OLD.ref OR NEW.provider_id IS NOT OLD.provider_id OR NEW.identity_id IS NOT OLD.identity_id OR NEW.kind IS NOT OLD.kind BEGIN SELECT RAISE(ABORT,'Durable playlist scope identity is immutable'); END;
